#include "boardwidget.h"
#include "sprites.h"
#include <QPainter>
#include <QMouseEvent>
#include <QKeyEvent>
#include <algorithm>
namespace retro {
BoardWidget::BoardWidget(QWidget* parent):QWidget(parent){setObjectName("board");setMinimumSize(440,440);setSizePolicy(QSizePolicy::Expanding,QSizePolicy::Expanding);setFocusPolicy(Qt::StrongFocus);setAccessibleName("Шахматна дъска");setAccessibleDescription("Стрелки: избор на поле. Enter: избор на фигура и ход.");}
QRect BoardWidget::boardRect()const{int cell=(std::min(width(),height())-48)/8;int side=cell*8;return {(width()-side)/2,(height()-side)/2,side,side};}
int BoardWidget::visualSquare(int r,int c)const{return flipped?r*16+7-c:(7-r)*16+c;}
int BoardWidget::squareAt(const QPoint& p)const{auto b=boardRect();if(!b.contains(p))return -1;int cell=b.width()/8;return visualSquare((p.y()-b.y())/cell,(p.x()-b.x())/cell);}
void BoardWidget::paintEvent(QPaintEvent*){QPainter p(this);p.setRenderHint(QPainter::Antialiasing,false);QRect b=boardRect();int cell=b.width()/8;p.fillRect(b.adjusted(-24,-24,24,24),QColor("#10211b"));p.setPen(QColor("#355548"));p.drawRect(b.adjusted(-23,-23,23,23));int check=position.inCheck()?position.king(position.turn):-1;
 for(int r=0;r<8;r++)for(int c=0;c<8;c++){int s=visualSquare(r,c),x=b.x()+c*cell,y=b.y()+r*cell;QRect q(x,y,cell,cell);p.fillRect(q,((s>>4)+(s&7))%2==0?QColor("#172f25"):QColor("#315440"));if(lastMove.valid()&&(s==lastMove.from||s==lastMove.to)){p.fillRect(q,QColor(223,211,111,35));p.fillRect(x+3,y+cell-6,8,3,QColor("#d4ca76"));}if(s==check){p.fillRect(q,QColor("#9e4334"));p.setPen(QPen(QColor("#ffb5a0"),2));p.drawRect(q.adjusted(2,2,-3,-3));}if(hint.valid()&&(s==hint.from||s==hint.to)){p.setPen(QPen(QColor("#f5ce7b"),3));p.drawRect(q.adjusted(4,4,-5,-5));}if(s==selected){p.fillRect(q,QColor(168,224,131,40));p.setPen(QPen(QColor("#b4f28a"),3));p.drawRect(q.adjusted(2,2,-3,-3));}int scale=std::max(1,cell/20);paintPiece(p,position.board[s],x+(cell-16*scale)/2,y+(cell-16*scale)/2,scale);p.setBrush(Qt::NoBrush);bool target=false;for(auto m:legalMoves)if(m.from==selected&&m.to==s)target=true;if(target){if(position.board[s]){p.setPen(QPen(QColor("#d3f2a8"),3));p.setBrush(Qt::NoBrush);p.drawRect(q.adjusted(4,4,-5,-5));}else p.fillRect(x+cell/2-4,y+cell/2-4,8,8,QColor("#d3f2a8"));}if(hasFocus()&&s==focusSquare){p.setPen(QPen(QColor("#f5ce7b"),2,Qt::DashLine));p.setBrush(Qt::NoBrush);p.drawRect(q.adjusted(1,1,-2,-2));}}
 p.setPen(QColor(0,0,0,12));for(int y=b.top();y<=b.bottom();y+=4)p.drawLine(b.left(),y,b.right(),y);
 p.setPen(QColor("#a1bda9"));for(int c=0;c<8;c++){QString file=QString(QChar('a'+(flipped?7-c:c)));p.drawText(QRect(b.x()+c*cell,b.y()-22,cell,20),Qt::AlignCenter,file);p.drawText(QRect(b.x()+c*cell,b.bottom()+2,cell,20),Qt::AlignCenter,file);}for(int r=0;r<8;r++){QString rank=QString::number(flipped?r+1:8-r);p.drawText(QRect(b.x()-22,b.y()+r*cell,20,cell),Qt::AlignCenter,rank);p.drawText(QRect(b.right()+2,b.y()+r*cell,20,cell),Qt::AlignCenter,rank);}p.setPen(QColor("#52715c"));p.setBrush(Qt::NoBrush);p.drawRect(b.adjusted(0,0,-1,-1));}
void BoardWidget::mousePressEvent(QMouseEvent* e){int s=squareAt(e->position().toPoint());if(s>=0){focusSquare=s;setFocus();emit squareChosen(s);}}
void BoardWidget::keyPressEvent(QKeyEvent* e){int row=flipped?focusSquare>>4:7-(focusSquare>>4),col=flipped?7-(focusSquare&7):focusSquare&7;switch(e->key()){case Qt::Key_Up:row=std::max(0,row-1);break;case Qt::Key_Down:row=std::min(7,row+1);break;case Qt::Key_Left:col=std::max(0,col-1);break;case Qt::Key_Right:col=std::min(7,col+1);break;case Qt::Key_Return:case Qt::Key_Enter:case Qt::Key_Space:emit squareChosen(focusSquare);return;default:QWidget::keyPressEvent(e);return;}focusSquare=visualSquare(row,col);update();e->accept();}
}
